-sm btn-outline-primary" href="?view=register&edit=<?=urlencode($r['id'])?>"><i class="bi bi-pencil"></i></a><form method="post" class="d-inline" onsubmit="return confirm('Xóa đơn này?')"><input type="hidden" name="action" value="delete_request"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form><?php endif;?><?php if($isAdmin&&$st==='pending'):?><form method="post" class="d-inline"><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn btn-sm btn-success" title="Duyệt"><i class="bi bi-check2"></i></button></form><form method="post" class="d-inline"><input type="hidden" name="action" value="reject"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="btn btn-sm btn-outline-danger" title="Từ chối"><i class="bi bi-x-lg"></i></button></form><?php endif;?></td></tr><?php }if(!$shown):?><tr><td colspan="5" class="text-center text-muted py-4">Chưa có đơn đăng ký.</td></tr><?php endif;?></tbody></table></div></section></div></div>
