ss="table table-hover mb-0"><thead><tr><th>STT</th><th>Học sinh</th><th>Lớp</th><th>Đăng ký ra/vào</th><th>Thực tế ra/vào</th><th>Lý do</th><th>Người đón</th><th>Đơn</th></tr></thead><tbody><?php foreach($history as $i=>$r):?><tr><td><?=$i+1?></td><td><strong><?=e($r['student_name']??'')?></strong></td><td><?=e($r['class_name']??'')?></td><td class="small"><?=e(date('d/m/Y H:i',strtotime($r['from_date'])))?><br>→ <?=e(date('d/m/Y H:i',strtotime($r['to_date'])))?></td><td class="small"><span class="text-success">Ra: <?=!empty($r['actual_exit_at'])?e(date('d/m H:i',strtotime($r['actual_exit_at']))):'Chưa xác nhận'?></span><br><span class="text-primary">Vào: <?=!empty($r['actual_return_at'])?e(date('d/m H:i',strtotime($r['actual_return_at']))):'Chưa xác nhận'?></span></td><td><?=e($r['reason']??'')?></td><td><?=e($r['pickup_name']??'')?><?php if(!empty($r['pickup_phone'])):?><div class="small text-muted"><?=e($r['pickup_phone'])?></div><?php endif;?></td><td><?php if(!empty($r['attachment'])):?><a target="_blank" class="btn btn-sm btn-outline-primary" href="<?=e(nt_exit_file_url($r['attachment']))?>"><i class="bi bi-file-earmark"></i></a><?php else:?>—<?php endif;?></td></tr><?php endforeach;if(!$history):?><tr><td colspan="8" class="text-center py-5 text-muted">Không có học sinh ra/vào trong khoảng đã chọn.</td></tr><?php endif;?></tbody></table></div></section>
<?php elseif($sub==='check'): $canCheck=nt_exit_is_current_duty();$foundId=trim((string)($_GET['found']??''));$found=$foundId?nt_exit_find($foundId):null;?><div class="qr-box"><section class="card"><div class="card-body"><h5><i class="bi bi-qr-code-scan"></i> Kiểm tra QR thẻ học sinh</h5><?php if(!$canCheck):?><div class="alert alert-warning">Chỉ giáo viên trực ngày <strong><?=date('d/m/Y')?></strong> hoặc quản trị được xác nhận ra/vào.</div><?php else:?><div class="small-note mb-2">Dùng camera điện thoại quét mã QR trên thẻ học sinh. Nếu trình duyệt không hỗ trợ quét trực tiếp, có thể dán mã/URL vào ô bên dưới.</div><video id="qrVideo" class="scan-video" playsinline muted></video><div class="d-flex gap-2 my-2"><button type="button" class="btn btn-primary" id="startScan"><i class="bi bi-camera"></i> Mở camera quét QR</button><button type="button" class="btn btn-outline-secondary" id="stopScan">Dừng</button></div><form method="post" id="qrForm"><input type="hidden" name="action" value="check_student"><div class="input-group"><input class="form-control" name="qr_value" id="qrValue" placeholder="Mã QR / URL / mã học sinh" required><button class="btn btn-dark">Kiểm tra</button></div></form><?php endif;?><?php if($found):?><hr><div class="alert alert-success"><strong><?=e($found['student_name']??'')?></strong> · <?=e($found['class_name']??'')?><br>Đã có đơn được duyệt: <?=e(date('d/m/Y H:i',strtotime($found['from_date'])))?> → <?=e(date('d/m/Y H:i',strtotime($found['to_date'])))?><br><span class="small"><?=e($found['reason']??'')?></span></div><div class="d-grid gap-2"><?php if(empty($found['actual_exit_at'])):?><form method="post"><input type="hidden" name="action" value="confirm_gate"><input type="hidden" name="id" value="<?=e($found['id'])?>"><input type="hidden" name="mode" value="exit"><button class="btn btn-success btn-lg w-100"><i class="bi bi-box-arrow-right"></i> XÁC NHẬN HỌC SINH RA</button></form><?php elseif(empty($found['actual_return_at'])):?><div class="text-center small text-success">Đã ra lúc <?=e(date('H:i d/m/Y',strtotime($found['actual_exit_at'])))?></div><form method="post"><input type="hidden" name="action" value="confirm_gate"><input type="hidden" name="id" value="<?=e($found['id'])?>"><input type="hidden" name="mode" value="return"><button class="btn btn-primary btn-lg w-100"><i class="bi bi-box-arrow-in-left"></i> XÁC NHẬN HỌC SINH VÀO</button></form><?php else:?><div class="alert alert-info mb-0">Học sinh đã hoàn tất lượt ra/vào này.</div><?php endif;?></div><?php endif;?></div></section></div>
<?php elseif($sub==='settings'):?><section class="card" style="max-width:850px"><div class="card-header fw-bold">Cài đặt đăng ký ra vào KTX</div><div class="card-body"><form method="post"><input type="hidden" name="action" value="save_settings"><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="registration_enabled" id="regEnabled" <?=!empty($settings['registration_enabled'])?'checked':''?>><label class="form-check-label fw-semibold" for="regEnabled">Mở chức năng đăng ký</label></div><div class="row g-3"><div class="col-md-3"><label class="form-label">Giờ mở đăng ký</label><input type="time" name="open_time" class="form-control" value="<?=e($settings['open_time'])?>"></div><div class="col-md-3"><label class="form-label">Giờ đóng đăng ký</label><input type="time" name="close_time" class="form-control" value="<?=e($settings['close_time'])?>"></div><div class="col-md-3"><label class="form-label">Dung lượng tối đa</label><div class="input-group"><input type="number" min="1" max="25" name="max_mb" class="form-control" value="<?=intval($settings['max_mb'])?>"><span class="input-group-text">MB</span></div></div><div class="col-md-3"><label class="form-label">Lịch sử mặc định</label><select name="history_default" class="form-select"><option value="day" <?=$settings['history_default']==='day'?'selected':''?>>Ngày hôm nay</option><option value="week" <?=$settings['history_default']==='week'?'selected':''?>>Tuần này</option><option value="month" <?=$settings['history_default']==='month'?'selected':''?>>Tháng này</option></select></div></div><hr><div class="row"><div class="col-md-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="require_attachment" id="reqAtt" <?=!empty($settings['require_attachment'])?'checked':''?>><label class="form-check-label" for="reqAtt">Bắt buộc có đơn đính kèm</label></div></div><div class="col-md-3"><div class="form-check"><input class="form-check-input" type="checkbox" name="allow_images" id="allowImg" <?=!empty($settings['allow_images'])?'checked':''?>><label class="form-check-label" for="allowImg">Cho phép ảnh</label></div></div><div class="col-md-3"><div class="form-check"><input class="form-check-input" type="checkbox" name="allow_pdf" id="allowPdf" <?=!empty($settings['allow_pdf'])?'checked':''?>><label class="form-check-label" for="allowPdf">Cho phép PDF</label></div></div><div class="col-md-2"><div class="form-check"><input class="form-check-input" type="checkbox" name="qr_enabled" id="qrEnabled" <?=!empty($settings['qr_enabled'])?'checked':''?>><label class="form-check-label" for="qrEnabled">Quét QR</label></div></div></div><div class="alert alert-info mt-3 mb-3"><i class="bi bi-google"></i> Hệ thống tự tạo và sử dụng riêng thư mục Google Drive <strong>“Đơn xin ra vào KTX”</strong> cho ảnh/PDF đơn xin.</div><button class="btn btn-primary"><i class="bi bi-floppy"></i> Lưu cài đặt</button></form></div></section><?php endif;?></main>
<script>
const startBtn=document.getElementById('startScan'),stopBtn=document.getElementById('stopScan'),video=document.getElementById('qrVideo'),input=document.getElementById('qrValue'),form=document.getElementById('qrForm');let stream=null,timer=null;
async function stopScan(){if(timer)clearInterval(timer);timer=null;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
if(stopBtn)stopBtn.onclick=stopScan;
if(startBtn)startBtn.onclick=async()=>{if(!('BarcodeDetector' in window)){alert('Trình duyệt này chưa hỗ trợ quét QR trực tiếp. Hãy dùng Chrome/Edge mới trên điện thoại hoặc nhập mã thủ công.');return;}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});timer=setInterval(async()=>{try{const codes=await detector.detect(video);if(codes.length){input.value=codes[0].rawValue;await stopScan();form.submit();}}catch(e){}},500);}catch(e){alert('Không mở được camera. Hãy cấp quyền camera cho trình duyệt.');}};
</script></body></html>
